#!/usr/bin/env bash
# Rebuilds the generated files: tokens/tokens.css, build/jarvis-mono.js and
# build/jarvis-mono.css. The app's package.json is untouched: esbuild and
# Tailwind run through npx at pinned versions (Tailwind matches the app's).
set -euo pipefail
cd "$(dirname "$0")/.."

node scripts/build-tokens.mjs

npx --yes esbuild@0.24.2 components/index.ts \
  --bundle --format=iife --global-name=JarvisMono --jsx=automatic --target=es2019 \
  --alias:react=./scripts/shims/react --alias:react-dom=./scripts/shims/react-dom \
  --legal-comments=none --minify \
  --banner:js="/* Jarvis Mono preview bundle: generated by scripts/build.sh from components/. Do not edit. */" \
  --outfile=build/jarvis-mono.js

npx --yes tailwindcss@3.4.17 -c scripts/tailwind.previews.cjs -i scripts/previews.input.css \
  -o build/jarvis-mono.css --minify

echo "built tokens/tokens.css, build/jarvis-mono.js, build/jarvis-mono.css"
